export function canonical35To38DatabaseBytes(scenario: Canonical35To38Scenario): Buffer {
  const recipe = Buffer.from(canonical35To38GeneratorSource, "utf8");
  const digest = (value: Uint8Array) => createHash("sha256").update(value).digest("hex");
  if (digest(recipe) !== canonical35To38Fixture.generatorSha256) throw new Error("CANONICAL35_38_RECIPE_MISMATCH");
  const packed = Buffer.from(compressed[scenario].base64, "base64");
  if (digest(packed) !== compressed[scenario].gzipSha256) throw new Error("CANONICAL35_38_GZIP_MISMATCH");
  const bytes = gunzipSync(packed, { maxOutputLength: 8 * 1024 * 1024 });
  const expected = canonical35To38Fixture.captures[scenario];
  if (bytes.length !== expected.databaseBytes || digest(bytes) !== expected.databaseSha256) throw new Error("CANONICAL35_38_IMAGE_MISMATCH");
  return bytes;
}
